/// 按名字找音符盒乐器，名字是方块状态里 `instrument` 属性的值。
pub fn note_block_instrument(name: &str) -> Option<&'static NoteBlockInstrumentDef> {
    NOTE_BLOCK_INSTRUMENTS.iter().find(|instrument| instrument.name == name)
}

