/// 按注册表名字找音效事件 ID。名字写错说明和官方版本不一致。
pub fn sound_event(name: &str) -> u16 {
    let index = SOUND_EVENT_IDS
        .binary_search_by(|(sound, _)| (*sound).cmp(name))
        .unwrap_or_else(|_| panic!("未知的音效事件：{name}"));
    SOUND_EVENT_IDS[index].1
}

/// 带 `jukebox_playable` 组件的物品 → `jukebox_song` 注册表 ID，按物品 ID 排序。
static JUKEBOX_SONGS: &[(i32, i32)] = &[
    (1460, 1), (1461, 5), (1462, 3), (1463, 4),
    (1464, 6), (1465, 7), (1466, 8), (1467, 9),
    (1468, 10), (1469, 11), (1470, 12), (1471, 17),
    (1472, 18), (1473, 21), (1474, 0), (1475, 20),
    (1476, 13), (1477, 16), (1478, 2), (1479, 14),
    (1480, 15), (1481, 19),
];

/// 物品带着的歌典 ID，没有 `jukebox_playable` 组件时是 `None`。
pub fn jukebox_song(item: i32) -> Option<i32> {
    JUKEBOX_SONGS
        .binary_search_by_key(&item, |&(item, _)| item)
        .ok()
        .map(|index| JUKEBOX_SONGS[index].1)
}

/// 声音来源的序号和名字，序号就是网络上 `writeEnum` 写的值。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SoundSource(u8);

impl SoundSource {
    pub const fn id(self) -> u8 {
        self.0
    }
    /// 序号就是官方 `SoundSource.ordinal()`。
    /// The number is official `SoundSource.ordinal()`.
    pub const fn from_id(id: u8) -> Self {
        Self(id)
    }
}

/// `master`。
pub const MASTER: SoundSource = SoundSource(0);
/// `music`。
pub const MUSIC: SoundSource = SoundSource(1);
/// `record`。
pub const RECORDS: SoundSource = SoundSource(2);
/// `weather`。
pub const WEATHER: SoundSource = SoundSource(3);
/// `block`。
pub const BLOCKS: SoundSource = SoundSource(4);
/// `hostile`。
pub const HOSTILE: SoundSource = SoundSource(5);
/// `neutral`。
pub const NEUTRAL: SoundSource = SoundSource(6);
/// `player`。
pub const PLAYERS: SoundSource = SoundSource(7);
/// `ambient`。
pub const AMBIENT: SoundSource = SoundSource(8);
/// `voice`。
pub const VOICE: SoundSource = SoundSource(9);
/// `ui`。
pub const UI: SoundSource = SoundSource(10);
